const line_width = 30;
var words: [100][]const u8 = undefined;
var count: usize = 0;
var tokens = std.mem.splitScalar(u8, paragraph, ' ');
while (tokens.next()) |word| {
    words[count] = word;
    count += 1;
var start: usize = 0;
while (start < count) {
    var end = start;
    var letters: usize = 0;
    while (end < count and letters + words[end].len + (end - start) <= line_width) {
        letters += words[end].len;
        end += 1;
    const n = end - start;
    try out.writeByte('|');
    if (end == count or n == 1) {
        for (words[start..end], 0..) |word, i| {
            if (i > 0)
                try out.writeByte(' ');
            try out.writeAll(word);
        try out.splatByteAll(' ', line_width - (letters + n - 1));
    } else {
        const spaces = line_width - letters;
        const gaps = n - 1;
        for (words[start..end], 0..) |word, i| {
            try out.writeAll(word);
            if (i < gaps) {
                const width = spaces / gaps + @as(usize, if (i < spaces % gaps) 1 else 0);
                try out.splatByteAll(' ', width);
    try out.writeAll("|\n");
